/* From Uiverse.io by ClawHack1 - Tags: form */
.__UIV_SCOPE__ .contact-form {
  background-color: #f2f2f2;
  padding: 20px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .contact-form label {
  color: black;
}

.__UIV_SCOPE__ .contact-form .heading {
  font-size: 24px;
  color: black;
  ;
  margin-bottom: 12px;
  font-weight: bold;
  display: block;
}

.__UIV_SCOPE__ .contact-form form {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .contact-form label {
  margin-bottom: 10px;
}

.__UIV_SCOPE__ textarea {
  resize: none;
  height: 80px;
  width: 200px;
}

.__UIV_SCOPE__ .contact-form input, .__UIV_SCOPE__ .contact-form textarea {
  padding: 10px;
  border: none;
  border-radius: 5px;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .contact-form input:focus, .__UIV_SCOPE__ .contact-form textarea:focus {
  outline: none;
  box-shadow: 0 0 5px #ff6384;
  transform: scale(1.05);
  transition: transform 0.3s ease-in-out;
}

.__UIV_SCOPE__ .contact-form button[type="submit"] {
  background-color: #ff6384;
  color: #fff;
  border: none;
  border-radius: 5px;
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
}

.__UIV_SCOPE__ .contact-form button[type="submit"]:hover {
  transform: scale(1.1);
  transition: transform 0.3s ease-in-out;
}
